@push('scripts')<script>(()=>{const form=document.querySelector('[data-complete-quote]');if(!form)return;const requests=new Map();const lookup=async input=>{const side=input.dataset.postal,select=form.querySelector(`[data-settlement="${side}"]`),location=form.querySelector(`[data-location="${side}"]`),postal=input.value.replace(/\D/g,'').slice(0,5);input.value=postal;requests.get(side)?.abort();select.disabled=true;select.replaceChildren(new Option(postal.length===5?'Consultando…':'Captura primero el CP',''));location.textContent=postal.length===5?'Consultando municipio y estado…':'Municipio y estado';if(postal.length!==5)return;const controller=new AbortController();requests.set(side,controller);try{const response=await fetch(`/codigos-postales/${postal}`,{headers:{Accept:'application/json'},signal:controller.signal}),data=await response.json();if(!response.ok)throw new Error(data.message);const colonies=data.colonias||[];select.replaceChildren();if(colonies.length!==1)select.add(new Option('Selecciona una colonia',''));colonies.forEach(c=>select.add(new Option(c.nombre,c.nombre)));select.disabled=!colonies.length;if(colonies.length===1)select.value=colonies[0].nombre;location.textContent=[data.municipio,data.estado].filter(Boolean).join(', ')}catch(error){if(error.name==='AbortError')return;select.replaceChildren(new Option('No fue posible consultar colonias',''));location.textContent=error.message||'Intenta nuevamente'}};form.querySelectorAll('[data-postal]').forEach(input=>{input.addEventListener('input',()=>lookup(input));if(/^\d{5}$/.test(input.value))lookup(input)});form.querySelectorAll('[data-saved-address]').forEach(select=>select.addEventListener('change',()=>{const data=select.selectedOptions[0]?.dataset.address;if(!data)return;const card=select.closest('.z-form-section'),address=JSON.parse(data);Object.entries(address).forEach(([key,value])=>{const field=card.querySelector(`[data-address-field="${key}"]`);if(field)field.value=value??''});const postal=card.querySelector('[data-postal]');lookup(postal).then(()=>{const settlement=card.querySelector('[data-settlement]');settlement.dataset.restore=address.settlement;setTimeout(()=>settlement.value=address.settlement,0)})}));const type=form.querySelector('[data-package-type]'),weight=form.querySelector('[data-weight]'),dims=form.querySelector('[data-dimensions]'),inputs=[...dims.querySelectorAll('input')],error=form.querySelector('[data-package-error]'),submit=form.querySelector('button[type=submit]');const sync=()=>{const box=type.value==='caja';dims.hidden=!box;weight.readOnly=!box;if(!box)weight.value=1;inputs.forEach(i=>i.required=box);const values=Object.fromEntries(inputs.map(i=>[i.dataset.dimension,Number(i.value||0)])),real=Number(weight.value||0),vol=box?values.length*values.width*values.height/5000:0,billable=box?Math.ceil(Math.max(real,vol)):1,invalid=box&&(real>40||values.length>60||values.width>50||values.height>40);form.querySelector('[data-real]').textContent=`${real.toFixed(2)} kg`;form.querySelector('[data-volumetric]').textContent=box?`${vol.toFixed(2)} kg`:'—';form.querySelector('[data-billable]').textContent=`${billable} kg`;error.hidden=!invalid;submit.disabled=invalid};[type,weight,...inputs].forEach(i=>i.addEventListener('input',sync));sync()})()</script>@endpush
